input.dsl:
workspace "Order Management" "Multi-file Structurizr workspace for the order management platform" {

    !identifiers hierarchical

    model {
customer = person "Customer" "A customer who places orders through the web store"
support = person "Support Agent" "A support agent who looks up and amends orders"
store = softwareSystem "Web Store" "The customer-facing web store where orders are placed" {
    web = container "Web App" "Server-rendered storefront and checkout" "Java/Spring" "Web"
    api = container "Order API" "REST API for order management" "Java/Spring" "Service"
    db = container "Order Database" "System of record for orders" "PostgreSQL" "Database"
    queue = container "Message Queue" "Buffers order events for asynchronous processing" "RabbitMQ" "Queue"
}

billing = softwareSystem "Billing System" "External billing and invoicing system" "External"
email = softwareSystem "Email Service" "External transactional email provider" "External"
customer -> store.web "places orders through" "HTTPS"
support -> store.api "looks up and amends orders via" "HTTPS"
store.web -> store.api "submits order requests to" "HTTP"
store.api -> store.db "persists orders in" "SQL"
store.api -> store.queue "publishes order events to" "AMQP" "Async"
store.queue -> billing "sends billing requests to" "AMQP" "Async"
store.queue -> email "sends order confirmation emails to" "AMQP" "Async"
    }

    views {
systemLandscape "Landscape" "All people and systems in the order management landscape" {
    include *
    autoLayout
    title "Order Management Landscape"
}
systemContext store "StoreContext" "Context diagram for the Web Store" {
    include *
    autoLayout
    title "Web Store System Context"
}
container store "StoreContainers" "Container diagram for the Web Store" {
    include *
    autoLayout
    title "Web Store Containers"
}
styles {
    element "Person" {
        shape Person
        background #08427B
        color #ffffff
    }
    element "Software System" {
        background #1168BD
        color #ffffff
    }
    element "External" {
        background #999999
        color #ffffff
    }
    element "Container" {
        background #438DD5
        color #ffffff
    }
    element "Web" {
        shape WebBrowser
    }
    element "Database" {
        shape Cylinder
    }
    element "Queue" {
        shape Pipe
    }
    relationship "Async" {
        style dashed
    }
}
    }
}

